mod core;
mod baseline;
#[path="../orbit-core/sparse.rs"]mod sparse;
#[path="../setup/fast.rs"]mod fast;
#[path="../multi/algebra.rs"]mod algebra;
#[allow(dead_code)]#[path="../cyclotomic-lp/ring.rs"]mod ring;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng};
fn run(c:&Curve,pt:(u64,u64),d:&Div,t:&Div,ell:u64,sm:u64,gate:bool)->Vec<core::Trace>{let mut traces=vec![];for seed in 1..=3{let out=core::solve(c,pt,d,t,ell,sm,seed,gate);let done=out.answer.is_some();traces.push(out);if done{break}}traces}
fn qualify(c:&Curve,d:&Div,t:&Div,ell:u64,lambda:u64,traces:&[core::Trace]){let r=ring::Ring::new(ell);for trace in traces{let seed=c.place(trace.points[1].0,trace.points[1].1);for(&p,h)in trace.points.iter().zip(&trace.labels){let v=h.map(|x|r.eval(x,lambda));assert_eq!(c.place(p.0,p.1),c.add(&c.add(&c.mul(t,v[0]),&c.mul(&seed,v[1])),&c.mul(d,v[2])));}if let Some((l,k))=trace.answer{assert_eq!(l,lambda);assert_eq!(c.mul(d,k),*t);}}}
fn main(){counted::disable();println!("p\tsm\tcase\trep\tarm\tmodulus\tk\texpected\tattempts\trows\tscans\tvisits\tcounts");let(mut calls,mut incomplete,mut restarts)=(0,0,0);
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,_,character)=fast::prepare(&c);let(_,_,degree,lambda)=algebra::certificate(&character,ell);assert_eq!(degree,1);let lambda=lambda.unwrap();let pt=fb[0];let base=c.place(pt.0,pt.1);assert!(c.is_zero(&c.mul(&base,ell)));
if p==601{let mut old=Rng::new(2026112900^p);let _=old.below(ell-1);let k=1+old.below(ell-1);let t=c.mul(&base,k);let trace=run(&c,pt,&base,&t,ell,1,true);assert!(trace[0].answer.is_none());qualify(&c,&base,&t,ell,lambda,&trace);eprintln!("KNOWN_STALL\tp={p}\tattempts={}\tfinal_k={}",trace.len(),trace.last().unwrap().answer.map_or("none".into(),|x|x.1.to_string()));}
let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let target=c.mul(&d,expected);let gate=run(&c,pt,&d,&target,ell,sm,true);qualify(&c,&d,&target,ell,lambda,&gate);let control=baseline::solve(&c,&d,&target,ell,sm,true);let mut prior=std::collections::BTreeMap::new();
for rep in 0..2{for n in 0..2{let arm=if rep==0{n}else{1-n};counted::reset();let(k,attempts,rows,scans,visits)=if arm==0{let r=baseline::solve(&c,&d,&target,ell,sm,false);assert_eq!((r.k,r.relations,r.anchors,r.parameter),(control.k,control.relations,control.anchors,control.parameter));(r.k,1,r.relations,r.anchors as usize,0)}else{let traces=run(&c,pt,&d,&target,ell,sm,false);assert_eq!(traces,gate);let attempts=traces.len();restarts+=attempts-1;(traces.last().unwrap().answer.map(|x|x.1),attempts,traces.iter().map(|x|x.rows).sum(),traces.iter().map(|x|x.scans).sum(),traces.iter().map(|x|x.visits).sum())};let counts=counted::snapshot();counted::disable();if let Some(k)=k{assert_eq!(k,expected);assert_eq!(c.mul(&d,k),target);}else{incomplete+=1;}let sig=(k,attempts,rows,scans,visits,counts.clone());if rep==1{assert_eq!(prior[&arm],sig);}else{prior.insert(arm,sig);}for(modulus,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);println!("{p}\t{sm}\t{case}\t{rep}\t{arm}\t{modulus}\t{}\t{expected}\t{attempts}\t{rows}\t{scans}\t{visits}\t{}",k.map_or("none".into(),|x|x.to_string()),v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}
}}}assert_eq!(calls,48);eprintln!("calls={calls} incomplete_calls={incomplete} candidate_restarts={restarts} fresh_targets=12 exact_repeats=true all_returned_scalars_and_diagnostic_labels_verify=true all_fallback_costs_charged=true");}
